pub(crate) fn property(c: char, bit: u16) -> bool {
    let n = c as u32;
    let i = PROPERTIES.partition_point(|x| x.1 < n);
    PROPERTIES
        .get(i)
        .is_some_and(|x| x.0 <= n && x.2 & bit != 0)
}
